import type { EmailMessage } from "./send";

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function layout(body: string): string {
  return `<!doctype html>
<html>
  <body style="margin:0;padding:24px;background:#f6f6f6;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
    <div style="max-width:480px;margin:0 auto;background:#fff;border-radius:8px;padding:32px">
      ${body}
      <p style="margin-top:32px;font-size:12px;color:#888">Notely</p>
    </div>
  </body>
</html>`;
}

function button(href: string, label: string): string {
  return `<a href="${escapeHtml(href)}" style="display:inline-block;padding:10px 18px;background:#111;color:#fff;border-radius:6px;text-decoration:none">${escapeHtml(label)}</a>`;
}

export function welcomeEmail(params: { to: string; name: string; appUrl: string }): EmailMessage {
  const dashboardUrl = `${params.appUrl}/dashboard`;
  return {
    to: params.to,
    subject: "Welcome to Notely",
    html: layout(`
      <h1 style="font-size:20px">Welcome, ${escapeHtml(params.name)}!</h1>
      <p>Your Notely account is ready. Jump in and start writing notes with your team.</p>
      <p>${button(dashboardUrl, "Open Notely")}</p>
    `),
    text: `Welcome, ${params.name}!\n\nYour Notely account is ready.\nOpen Notely: ${dashboardUrl}\n`,
  };
}

export function passwordResetEmail(params: {
  to: string;
  name: string;
  resetUrl: string;
  expiresInMinutes: number;
}): EmailMessage {
  return {
    to: params.to,
    subject: "Reset your Notely password",
    html: layout(`
      <h1 style="font-size:20px">Reset your password</h1>
      <p>Hi ${escapeHtml(params.name)}, we received a request to reset your Notely password.</p>
      <p>${button(params.resetUrl, "Reset password")}</p>
      <p style="font-size:14px;color:#555">This link expires in ${params.expiresInMinutes} minutes and can be used once.
      If you didn't request this, you can ignore this email.</p>
    `),
    text:
      `Hi ${params.name},\n\nReset your Notely password: ${params.resetUrl}\n\n` +
      `This link expires in ${params.expiresInMinutes} minutes and can be used once. ` +
      `If you didn't request this, ignore this email.\n`,
  };
}
EOF
